-- A view's row type works like a table's: values, casts, arrays, whole-row
-- references, columns and domains, and DROP reaches every user of it.
CREATE SCHEMA vrt;
SET search_path = vrt;
CREATE TABLE t (a int, b text);
INSERT INTO t VALUES (1, 'x');
CREATE VIEW v AS SELECT a, b, a * 2 AS c FROM t;
SELECT ROW(1, 'y', 2)::v;
SELECT '(1,y,2)'::v;
SELECT ('(1,y,2)'::v).c;
SELECT v FROM v;
SELECT (v).b FROM v;
SELECT ARRAY[ROW(1, 'y', 2)::v];
SELECT '{"(1,y,2)"}'::v[];
SELECT pg_typeof(v) FROM v;
SELECT pg_typeof(ARRAY[t]) FROM t;
SELECT ARRAY[t] FROM t;
SELECT '{"(3,z)"}'::t[];
CREATE TABLE holder (x v, y v[], z t[]);
INSERT INTO holder SELECT v, ARRAY[v], ARRAY[ROW(5,'q')::t] FROM v;
SELECT * FROM holder;
SELECT (x).c, y[1].b, z[1].a FROM holder;
CREATE FUNCTION fv(v) RETURNS int LANGUAGE sql AS 'SELECT $1.c';
SELECT fv(v) FROM v;
CREATE FUNCTION gv() RETURNS SETOF v LANGUAGE sql AS 'SELECT * FROM v';
SELECT * FROM gv();
DROP VIEW v;
DROP VIEW v CASCADE;
SELECT * FROM holder;
CREATE VIEW v2 AS SELECT a FROM t;
CREATE TABLE holder2 (x v2);
CREATE OR REPLACE VIEW v2 AS SELECT a, b FROM t;
ALTER VIEW v2 RENAME COLUMN a TO aa;
SELECT * FROM holder2;
DROP TABLE holder2;
DROP TABLE t CASCADE;
CREATE TABLE t (a int, b varchar(4));
INSERT INTO t VALUES (1, 'x'), (2, 'yy');
CREATE VIEW v AS SELECT a, b, a * 2 AS c FROM t;
CREATE TABLE h (id int, x v, xs v[]);
INSERT INTO h VALUES (1, '(1,x,2)', '{"(1,x,2)","(3,zz,6)"}');
INSERT INTO h SELECT 2, v, ARRAY[v] FROM v WHERE a = 2;
SELECT * FROM h ORDER BY id;
SELECT (x).b, xs[2].c FROM h ORDER BY id;
INSERT INTO h VALUES (3, '(1,toolong,2)', NULL);
SELECT ROW(1, 'abcdef', 3)::v;
SELECT pg_typeof(xs) FROM h LIMIT 1;
\d h
SELECT pg_describe_object(classid, objid, objsubid) AS dependent, pg_describe_object(refclassid, refobjid, refobjsubid) AS referenced, deptype FROM pg_depend WHERE refobjid = 'v'::regtype OR refobjid = 'v[]'::regtype ORDER BY 1, 2;
CREATE FUNCTION mk(int) RETURNS v LANGUAGE sql AS 'SELECT a, b, c FROM v WHERE a = $1';
SELECT mk(2), (mk(2)).c;
SELECT * FROM mk(1);
CREATE FUNCTION pl(r v) RETURNS text LANGUAGE plpgsql AS $$ BEGIN RETURN r.b || r.c; END $$;
SELECT pl(v) FROM v ORDER BY a;
SELECT v = ROW(1, 'x', 2)::v FROM v ORDER BY a;
SELECT array_agg(v ORDER BY a) FROM v;
ALTER VIEW v RENAME COLUMN c TO doubled;
SELECT (x).doubled FROM h ORDER BY id;
CREATE OR REPLACE VIEW v AS SELECT a, b, a * 2 AS doubled, 'n'::text AS note FROM t;
SELECT x FROM h ORDER BY id;
SELECT v FROM v ORDER BY a;
DROP TABLE t;
DROP TABLE t CASCADE;
DROP VIEW v;
DROP VIEW v CASCADE;
SELECT * FROM h ORDER BY id;
DROP TABLE h;
CREATE TABLE t (a int, b varchar(4));
CREATE TYPE ct AS (a int, b varchar(4));
SELECT ROW(1, 'abcdef')::t;
SELECT ROW(1, 'abcdef')::ct;
SELECT CAST(ROW(1, 'abcdef') AS ct);
SELECT '(1,abcdef)'::ct;
SELECT ROW(1.7, 'ab')::ct;
DROP TABLE t;
DROP TYPE ct;
CREATE TYPE c2 AS (a int, b varchar(4));
SELECT ROW('7'::text, 'x')::c2;
SELECT ROW(1.5::numeric, 'x')::c2;
CREATE TABLE ins (v c2);
INSERT INTO ins VALUES (ROW(1, 'abcdef'));
INSERT INTO ins VALUES (ROW(1, 'abcd'));
SELECT '{"(1,abcdef)"}'::c2[];
SELECT ARRAY[ROW(1, 'abcdef')]::c2[];
DROP TABLE ins;
DROP TYPE c2;
CREATE TABLE t (a int, b text);
CREATE VIEW v AS SELECT a, b FROM t;
CREATE DOMAIN dt AS t CHECK ((VALUE).a > 0);
CREATE DOMAIN dv AS v CHECK ((VALUE).a > 0);
CREATE DOMAIN dva AS v[];
CREATE TABLE u (x dv, y dt);
SELECT ROW(1, 'z')::dv, ROW(1, 'q')::dt;
DROP VIEW v;
DROP VIEW v CASCADE;
DROP TABLE t;
DROP TABLE t CASCADE;
SELECT count(*) FROM pg_type WHERE typname IN ('dt', 'dv', 'dva');
\d u
CREATE SCHEMA s;
CREATE TABLE s.t2 (a int);
CREATE DOMAIN s.d2 AS s.t2;
DROP SCHEMA s CASCADE;
CREATE TABLE t3 (a int);
CREATE VIEW v3 AS SELECT a FROM t3;
CREATE DOMAIN d3 AS v3;
DROP TABLE t3 CASCADE;
SELECT count(*) FROM pg_type WHERE typname = 'd3';
DROP TABLE u;
CREATE TYPE pt AS (x int, y int);
CREATE TABLE a (p pt[], q int[]);
INSERT INTO a VALUES (ARRAY[ROW(1,2)::pt, ROW(3,4)::pt], ARRAY[5,6]);
SELECT p[1].x, p[2].y FROM a;
SELECT a.p[1].x FROM a;
SELECT (p[1]).x FROM a;
SELECT p[1].* FROM a;
SELECT q[1].x FROM a;
SELECT p[1:2].x FROM a;
SELECT p[1].x.y FROM a;
SELECT p[1].nope FROM a;
DROP TABLE a;
DROP TYPE pt;
CREATE TYPE pt AS (x int, y int);
CREATE TABLE a (p pt[], q int[]);
INSERT INTO a VALUES (ARRAY[ROW(1,2)::pt, ROW(3,4)::pt], ARRAY[5,6]);
SELECT (p[1]).* FROM a;
SELECT (p[1]).nope FROM a;
SELECT (p[1:2]).x FROM a;
SELECT pg_typeof(p[1]) FROM a;
DROP TABLE a;
DROP TYPE pt;
RESET search_path;
DROP SCHEMA vrt CASCADE;
